namespace ghidra.app.plugin.core.functiongraph;

using ghidra.graph.viewer;

/**
 * An enum for mapping the {@link PathHighlightMode} to values for use in UI actions.
 */
public class EdgeDisplayType
{	public static readonly EdgeDisplayType PathsToVertex = new();
	public static readonly EdgeDisplayType PathsFromVertex = new();
	public static readonly EdgeDisplayType PathsFromToVertex = new();
	public static readonly EdgeDisplayType Cycles = new();
	public static readonly EdgeDisplayType AllCycles = new();
	public static readonly EdgeDisplayType PathsFromVertexToVertex = new();
	public static readonly EdgeDisplayType ScopedFlowsFromVertex = new();
	public static readonly EdgeDisplayType ScopedFlowsToVertex = new();
	public static readonly EdgeDisplayType Off = new();


	public PathHighlightMode getAsPathHighlightHoverMode() {
		switch (this) {
			case PathsToVertex:
				return PathHighlightMode.IN;
			case PathsFromVertex:
				return PathHighlightMode.OUT;
			case PathsFromToVertex:
				return PathHighlightMode.INOUT;
			case Cycles:
				return PathHighlightMode.CYCLE;
			case AllCycles:
				return PathHighlightMode.ALLCYCLE;
			case PathsFromVertexToVertex:
				return PathHighlightMode.PATH;
			case ScopedFlowsFromVertex:
				return PathHighlightMode.SCOPED_FORWARD;
			case ScopedFlowsToVertex:
				return PathHighlightMode.SCOPED_REVERSE;
			case Off:
			default:
				return PathHighlightMode.OFF;
		}
	}
}
